const verificationId = $input.first().json.body.verification_id;

const data = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://ceogbuepvunwyavltcgu.supabase.co/rest/v1/verifications?id=eq.' + verificationId + '&select=*',
  headers: {
    'apikey': 'PEGAR_ANON_KEY',
    'Authorization': 'Bearer PEGAR_SERVICE_KEY'
  },
  json: true
});

if (!data || data.length === 0) {
  throw new Error('Verification not found');
}

return [{ json: data[0] }];

const openaiResponse = $input.first().json;
const v = $('Get Verification').item.json;

try {
  const content = openaiResponse.choices[0].message.content;
  const parsed = JSON.parse(content);

  const extractedName = (parsed.extracted_data?.full_name || '').toLowerCase().trim();
  const operatorName = (v.first_name + ' ' + v.last_name).toLowerCase().trim();
  const nameMatch = extractedName.includes(operatorName) || operatorName.includes(extractedName);

  const extractedDni = (parsed.extracted_data?.dni_number || '').replace(/[^0-9]/g, '');
  const operatorDni = (v.dni || '').replace(/[^0-9]/g, '');
  const dniMatch = extractedDni === operatorDni;

  const overallScore = parsed.overall_score || 0;
  let recommendation = parsed.recommendation || 'low_risk';

  return [{
    json: {
      verification_id: v.id,
      extracted_name: parsed.extracted_data?.full_name || '',
      extracted_dni: parsed.extracted_data?.dni_number || '',
      extracted_birth_date: parsed.extracted_data?.birth_date || '',
      dni_front_score: parsed.dni_front?.score || 0,
      dni_back_score: parsed.dni_back?.score || 0,
      dni_front_findings: parsed.dni_front?.findings || [],
      dni_back_findings: parsed.dni_back?.findings || [],
      overall_score: overallScore,
      fraud_signals: parsed.fraud_signals || [],
      data_match: {
        name_match: nameMatch,
        dni_match: dniMatch,
        card_match: false,
        operator_name: v.first_name + ' ' + v.last_name,
        extracted_name: parsed.extracted_data?.full_name || '',
        operator_dni: v.dni,
        extracted_dni: parsed.extracted_data?.dni_number || ''
      },
      data_consistency: parsed.data_consistency || {},
      summary: parsed.summary || [],
      recommendation: recommendation,
      raw_response: openaiResponse,
      analyzed_at: new Date().toISOString()
    }
  }];
} catch (error) {
  return [{
    json: {
      verification_id: v.id,
      extracted_name: '',
      extracted_dni: '',
      extracted_birth_date: '',
      dni_front_score: 0,
      dni_back_score: 0,
      dni_front_findings: [],
      dni_back_findings: [],
      overall_score: 0,
      fraud_signals: [{ signal: 'analysis_error', confidence: 100, description: 'Error al analizar: ' + error.message }],
      data_match: {},
      data_consistency: {},
      summary: ['Error al procesar el análisis'],
      recommendation: 'medium_risk',
      raw_response: openaiResponse,
      analyzed_at: new Date().toISOString()
    }
  }];
}
